"use client";

/**
 * RouteRecommendationResultSection — Section 4
 * The full Route Recommendation Result dossier.
 *
 * Position: after Popular/Preset Routes, before Day-by-Day Itinerary.
 * Anchor: #route-recommendation-result
 * Semantics: <section aria-labelledby="route-result-title">
 *
 * States handled:
 * - PRISTINE (null result): not rendered / hidden
 * - LOADING: RouteResultSkeleton
 * - DYNAMIC_SUCCESS, PRESET_SUCCESS: full dossier
 * - FALLBACK: full dossier + fallback disclosure
 * - ADJUSTED: full dossier + adjustment note
 * - RESTORED: full dossier + restored label
 * - ERROR: RouteResultErrorState
 *
 * Layout:
 * - Desktop ≥1024: split 5/7 (visual | content)
 * - Tablet 768–1023: stacked visual above content
 * - Mobile <768: single column
 */

import { useEffect, useRef, useState, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import type { RouteRecommendation, RoutePlannerFormValues, RoutePlannerStatus } from "@/types/route-planner";
import type { RouteItinerary } from "@/lib/routes/itinerary/routeItinerarySchema";
import { deriveRouteMatchType } from "@/lib/routes/routeResultHelpers";
import { trackRoutePlannerEvent } from "@/lib/routes/routePlannerAnalytics";
import { useLanguage } from "@/context/app-context";

// Sub-components
import { RouteResultSkeleton } from "./RouteResultSkeleton";
import { RouteResultErrorState } from "./RouteResultErrorState";
import { RouteResultStatusBar } from "./RouteResultStatusBar";
import { RouteResultVisual } from "./RouteResultVisual";
import { RouteResultHeader } from "./RouteResultHeader";
import { RouteReasonPanel } from "./RouteReasonPanel";
import { PreferenceMatchSummary } from "./PreferenceMatchSummary";
import { RouteOverviewRibbon } from "./RouteOverviewRibbon";
import { RouteResultMetadata } from "./RouteResultMetadata";
import { RouteResultActions } from "./RouteResultActions";
import { RouteResultDisclosure } from "./RouteResultDisclosure";
import { DayByDayItinerarySection } from "@/components/routes/day-by-day-itinerary/DayByDayItinerarySection";
import { RouteMapTransportSection } from "@/components/routes/route-map-transport";
import { RouteReadinessSection } from "@/components/routes/route-readiness";
import { RouteSaveRaniSection } from "@/components/routes/route-save-rani";

interface RouteRecommendationResultSectionProps {
  result: RouteRecommendation | null;
  status: RoutePlannerStatus;
  adjustmentNote: string | null;
  values: RoutePlannerFormValues;
  resultSource: "form" | "preset" | "url";
  onEdit: () => void;
  onReset: () => void;
  /** When true, this was an explicit user submit (focus heading) */
  focusOnReveal?: boolean;
}

export function RouteRecommendationResultSection({
  result,
  status,
  adjustmentNote,
  values,
  resultSource,
  onEdit,
  onReset,
  focusOnReveal = false,
}: RouteRecommendationResultSectionProps) {
  const { language } = useLanguage();
  const locale = language as "id" | "en";
  const headingRef = useRef<HTMLHeadingElement>(null);
  const isPresetSource = resultSource === "preset";

  // ── Section 6 state: resolved itinerary + bidirectional selection ──
  const [resolvedItinerary, setResolvedItinerary] = useState<RouteItinerary | null>(null);
  // Selection from itinerary → map
  const [mapExternalSelection, setMapExternalSelection] = useState<{
    dayNumber: number;
    dayId: string;
    stopId?: string;
    segmentIds?: string[];
  } | null>(null);
  // Selection from map → itinerary (day number to open)
  const [itineraryExternalDay, setItineraryExternalDay] = useState<number | null>(null);

  const handleViewInMap = useCallback((context: {
    dayNumber: number;
    dayId: string;
    stopId?: string;
    segmentIds?: string[];
  }) => {
    setMapExternalSelection(context);
  }, []);

  const handleViewInItinerary = useCallback((dayNumber: number) => {
    setItineraryExternalDay(dayNumber);
    // Reset after a tick so it can be re-triggered with same day
    setTimeout(() => setItineraryExternalDay(null), 500);
  }, []);

  // Reset section 6 state when result changes
  useEffect(() => {
    setMapExternalSelection(null);
    setItineraryExternalDay(null);
  }, [result?.id]);

  // ── Focus management: only focus after explicit submit ──
  useEffect(() => {
    if (focusOnReveal && result && status !== "loading" && headingRef.current) {
      // Small delay to let animation settle
      const id = setTimeout(() => {
        headingRef.current?.focus();
      }, 400);
      return () => clearTimeout(id);
    }
  }, [result, status, focusOnReveal]);

  // ── Analytics: track when result is viewed ──
  useEffect(() => {
    if (!result || status === "loading") return;
    trackRoutePlannerEvent("route_result_viewed");
    if (status === "fallback") {
      trackRoutePlannerEvent("route_result_fallback_loaded");
    } else if (resultSource === "preset") {
      trackRoutePlannerEvent("route_result_preset_loaded");
    } else {
      trackRoutePlannerEvent("route_result_dynamic_loaded");
    }
  }, [result?.id, status]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── PRISTINE: return null — no fake personal recommendation ──
  if (!result && status === "idle") {
    return null;
  }

  // ── LOADING ──
  if (status === "loading") {
    return <RouteResultSkeleton isPreset={isPresetSource} />;
  }

  // ── ERROR ──
  if (status === "error" && !result) {
    return (
      <RouteResultErrorState
        onRetry={onReset}
        onEdit={onEdit}
        locale={locale}
      />
    );
  }

  // ── No result but not loading/error — shouldn't happen but guard ──
  if (!result) return null;

  // ── Derive match type from status + recommendation ──
  const matchType = deriveRouteMatchType(status, result, resultSource);
  const isAdjusted = !!adjustmentNote && matchType !== "fallback";

  return (
    <AnimatePresence mode="wait">
      <motion.section
        key={result.id}
        id="route-recommendation-result"
        aria-labelledby="route-result-title"
        className="w-full scroll-mt-32"
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: -8 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
      >
        {/* Dossier card — Editorial Style */}
        <div className="w-full rounded-[36px] bg-[#FFFDF8] border border-[#E8E0CE] p-6 md:p-8 lg:p-12 shadow-[0_8px_32px_rgba(13,27,42,0.04)] relative">

          {/* Status bar */}
          <div className="flex items-center gap-3 mb-8 lg:mb-10">
            <RouteResultStatusBar
              matchType={matchType}
              isAdjusted={isAdjusted}
              locale={locale}
            />
          </div>

          {/* Main dossier: Editorial Grid */}
          <div className="flex flex-col lg:flex-row gap-8 lg:gap-16">

            {/* LEFT PANEL: Visual + Route Ribbon */}
            <div className="lg:w-2/5 flex flex-col gap-6 lg:gap-8">
              <RouteResultVisual result={result} locale={locale} />

              {/* Route ribbon below visual on desktop, inside content on mobile */}
              <div className="hidden lg:block pt-6 border-t border-[#E8E0CE]">
                <RouteOverviewRibbon result={result} locale={locale} />
              </div>
            </div>

            {/* RIGHT PANEL: Content */}
            <div className="lg:w-3/5 flex flex-col gap-8 lg:gap-10">

              {/* Header: eyebrow + title + promise */}
              {/* Attach ref for focus management */}
              <div ref={headingRef as React.RefObject<HTMLDivElement>}>
                <RouteResultHeader result={result} locale={locale} />
              </div>

              {/* Route ribbon — mobile only (above reason) */}
              <div className="lg:hidden">
                <RouteOverviewRibbon result={result} locale={locale} />
              </div>

              {/* Expert's Note / Why recommended */}
              <RouteReasonPanel result={result} values={values} locale={locale} />

              {/* Travel Profile (Metadata + Preference Match) */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 border-y border-[#E8E0CE] py-8">
                <PreferenceMatchSummary result={result} values={values} locale={locale} />
                <RouteResultMetadata result={result} values={values} locale={locale} />
              </div>

              {/* Actions & Disclosures */}
              <div className="flex flex-col gap-6 pt-2">
                <RouteResultActions
                  result={result}
                  values={values}
                  onEdit={onEdit}
                  onReset={onReset}
                  locale={locale}
                />
                <RouteResultDisclosure
                  matchType={matchType}
                  adjustmentNote={adjustmentNote}
                  locale={locale}
                />
              </div>
            </div>
          </div>
        </div>

        {/* Day-by-day itinerary section */}
        <div className="w-full">
          <DayByDayItinerarySection
            result={result}
            status={status}
            onViewInMap={handleViewInMap}
            externalActiveDay={itineraryExternalDay}
            onItineraryResolved={setResolvedItinerary}
          />
        </div>

        {/* Section 6: Route Map + Transport Summary */}
        <div className="w-full">
          <RouteMapTransportSection
            result={result}
            itinerary={resolvedItinerary}
            status={status}
            externalDaySelection={mapExternalSelection}
            onViewInItinerary={handleViewInItinerary}
          />
        </div>

        {/* Section 7: Travel Readiness Dossier (Budget, Culinary, Etiquette, Checklist) */}
        <div className="w-full">
          <RouteReadinessSection
            result={result}
            itinerary={resolvedItinerary}
            status={status}
          />
        </div>

        {/* Section 8: Save to Passport + Ask RANI */}
        <div className="w-full">
          <RouteSaveRaniSection
            result={result}
            itinerary={resolvedItinerary}
            values={values}
            resultSource={resultSource}
            onApplyDraft={(draft) => {
              // Implementation detail for applying a draft. 
              // Since this is MVP, the draft may be a mock. 
              // A real implementation would lift this state to `RouteAtelier` or `page.tsx`.
              console.log("Applying draft", draft);
            }}
          />
        </div>
      </motion.section>
    </AnimatePresence>
  );
}

import { useState } from "react";
import { Bookmark, CheckCircle, ExternalLink, AlertTriangle } from "lucide-react";
import { PassportSavedRoute } from "@/lib/types";
import { usePassport } from "@/context/app-context";
import Link from "next/link";

interface PassportSaveLaneProps {
  savedRoute: PassportSavedRoute;
  locale: "id" | "en";
}

export function PassportSaveLane({ savedRoute, locale }: PassportSaveLaneProps) {
  const { passport, saveRouteWithDetails, removeRouteWithDetails } = usePassport();
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const isSaved = passport.savedRoutes.includes(savedRoute.routeId);

  const handleSave = () => {
    try {
      setErrorMsg(null);
      if (isSaved) {
        removeRouteWithDetails(savedRoute.routeId);
      } else {
        saveRouteWithDetails(savedRoute);
      }
    } catch (e: any) {
      if (e.message === "QUOTA_EXCEEDED") {
        setErrorMsg(
          locale === "en"
            ? "You have saved 20 routes. Remove an old route from your Passport to save a new one."
            : "Kamu telah menyimpan 20 rute. Hapus salah satu rute lama dari Passport untuk menyimpan rute baru."
        );
      } else {
        setErrorMsg(locale === "en" ? "Failed to save route." : "Gagal menyimpan rute.");
      }
    }
  };

  return (
    <div className="flex flex-col gap-4 border border-[#E8E0CE] rounded-2xl p-6 bg-white">
      <div className="flex items-start justify-between">
        <div className="flex flex-col gap-2">
          <h4 className="font-display font-medium text-lg text-[#2C3E50]">
            Nusa Passport
          </h4>
          <p className="text-sm text-[#5C6D7E] leading-relaxed">
            {isSaved
              ? (locale === "en" ? "This route is saved in your Passport." : "Rute ini telah tersimpan di Passport kamu.")
              : (locale === "en" ? "Save this route to access it later and continue your journey planning." : "Simpan rute ini untuk diakses kembali dan melanjutkan rencana perjalananmu.")}
          </p>
        </div>
        <div className="p-3 bg-[#FAF8F5] rounded-full">
          <Bookmark className="w-6 h-6 text-[#D4AF37]" />
        </div>
      </div>

      {errorMsg && (
        <div className="bg-red-50 text-red-700 p-3 rounded-lg flex items-start gap-2 text-sm mt-2 border border-red-100">
          <AlertTriangle className="w-4 h-4 mt-0.5 shrink-0" />
          <p>{errorMsg}</p>
        </div>
      )}

      <div className="mt-2 flex flex-col gap-3">
        <button
          onClick={handleSave}
          className={`w-full py-3 px-4 rounded-xl font-medium transition-colors flex items-center justify-center gap-2 ${
            isSaved
              ? "bg-[#FAF8F5] text-[#2C3E50] border border-[#E8E0CE] hover:bg-[#F0EBE1]"
              : "bg-[#2C3E50] text-white hover:bg-[#1A252F]"
          }`}
        >
          {isSaved ? (
            <>
              <CheckCircle className="w-5 h-5" />
              {locale === "en" ? "Saved to Passport" : "Tersimpan di Passport"}
            </>
          ) : (
            <>
              <Bookmark className="w-5 h-5" />
              {locale === "en" ? "Save to Passport" : "Simpan ke Passport"}
            </>
          )}
        </button>

        {isSaved && (
          <Link
            href="/passport"
            className="w-full py-3 px-4 rounded-xl font-medium text-[#2C3E50] border border-[#E8E0CE] hover:bg-[#FAF8F5] transition-colors flex items-center justify-center gap-2"
          >
            {locale === "en" ? "Open Passport" : "Buka Passport"}
            <ExternalLink className="w-4 h-4" />
          </Link>
        )}
      </div>
    </div>
  );
}

import { useState } from "react";
import { Sparkles, Loader2, ArrowRightCircle } from "lucide-react";
import { RouteAdjustmentIntent, RouteAdjustmentDraft } from "@/lib/routes/save-rani/types";
import { RouteRecommendation, RoutePlannerFormValues } from "@/types/route-planner";
import { RouteItinerary } from "@/lib/routes/itinerary/routeItinerarySchema";
import { resolveRouteAdjustment } from "@/lib/routes/save-rani/resolveRouteAdjustment";
import { RouteAdjustmentDiff } from "./RouteAdjustmentDiff";

interface RaniAdjustmentLaneProps {
  result: RouteRecommendation;
  itinerary: RouteItinerary;
  values: RoutePlannerFormValues;
  locale: "id" | "en";
  onApplyDraft: (draft: RouteAdjustmentDraft) => void;
}

export function RaniAdjustmentLane({ result, itinerary, values, locale, onApplyDraft }: RaniAdjustmentLaneProps) {
  const [isResolving, setIsResolving] = useState(false);
  const [activeDraft, setActiveDraft] = useState<RouteAdjustmentDraft | null>(null);

  const quickPrompts: { intent: RouteAdjustmentIntent; label: string }[] = [
    { intent: "REDUCE_BUDGET", label: locale === "en" ? "Reduce budget" : "Kurangi budget" },
    { intent: "SLOWER_PACE", label: locale === "en" ? "More relaxed pace" : "Lebih santai" },
    { intent: "REDUCE_TRANSFERS", label: locale === "en" ? "Less transfers" : "Kurangi pindah" },
  ];

  const handlePromptClick = async (intent: RouteAdjustmentIntent) => {
    setIsResolving(true);
    setActiveDraft(null);
    try {
      const draft = await resolveRouteAdjustment(intent, result, itinerary, values, locale);
      // Simulate network/think delay for RANI UX
      setTimeout(() => {
        setActiveDraft(draft);
        setIsResolving(false);
      }, 600);
    } catch (e) {
      setIsResolving(false);
    }
  };

  const handleCancelDraft = () => {
    setActiveDraft(null);
  };

  const handleApplyDraft = () => {
    if (activeDraft) {
      onApplyDraft(activeDraft);
      setActiveDraft(null);
    }
  };

  return (
    <div className="flex flex-col border border-[#D4AF37]/30 rounded-2xl p-6 bg-gradient-to-br from-[#FFFDF8] to-[#F9F6F0] relative overflow-hidden">
      {/* RANI background decoration */}
      <div className="absolute -top-10 -right-10 w-40 h-40 bg-[#D4AF37]/5 rounded-full blur-2xl pointer-events-none" />

      <div className="flex items-start gap-4 mb-5 relative z-10">
        <div className="w-12 h-12 bg-gradient-to-br from-[#D4AF37] to-[#B3932F] rounded-xl flex items-center justify-center shrink-0 shadow-sm text-white">
          <Sparkles className="w-6 h-6" />
        </div>
        <div>
          <h4 className="font-display font-medium text-lg text-[#2C3E50]">
            Ask RANI
          </h4>
          <p className="text-sm text-[#5C6D7E] leading-relaxed">
            {locale === "en" 
              ? "Need adjustments? I can help you find a better alternative without starting over." 
              : "Ada yang kurang pas? Saya bisa bantu carikan alternatif rute tanpa harus mengulang dari awal."}
          </p>
        </div>
      </div>

      {!activeDraft && (
        <div className="flex flex-wrap gap-2 relative z-10 mt-2">
          {quickPrompts.map((prompt) => (
            <button
              key={prompt.intent}
              onClick={() => handlePromptClick(prompt.intent)}
              disabled={isResolving}
              className="px-4 py-2 bg-white border border-[#E8E0CE] text-[#2C3E50] text-sm font-medium rounded-full hover:border-[#D4AF37] hover:text-[#D4AF37] transition-colors disabled:opacity-50 flex items-center gap-2"
            >
              {prompt.label}
              <ArrowRightCircle className="w-4 h-4 opacity-70" />
            </button>
          ))}
        </div>
      )}

      {isResolving && (
        <div className="flex items-center gap-3 text-[#D4AF37] font-medium text-sm mt-6 p-4 bg-white/50 rounded-xl border border-[#D4AF37]/20">
          <Loader2 className="w-5 h-5 animate-spin" />
          {locale === "en" ? "RANI is preparing an alternative..." : "RANI sedang menyusun alternatif..."}
        </div>
      )}

      {activeDraft && !isResolving && (
        <RouteAdjustmentDiff 
          draft={activeDraft} 
          locale={locale} 
          onApply={handleApplyDraft} 
          onCancel={handleCancelDraft} 
        />
      )}
    </div>
  );
}

import { RouteAdjustmentDraft, RouteAdjustmentChange } from "@/lib/routes/save-rani/types";
import { ArrowRight, CheckCircle2, ShieldAlert } from "lucide-react";

interface RouteAdjustmentDiffProps {
  draft: RouteAdjustmentDraft;
  locale: "id" | "en";
  onApply: () => void;
  onCancel: () => void;
}

export function RouteAdjustmentDiff({ draft, locale, onApply, onCancel }: RouteAdjustmentDiffProps) {
  return (
    <div className="bg-white border border-[#D4AF37]/40 rounded-2xl p-5 md:p-6 shadow-sm mt-6">
      <div className="flex items-start justify-between mb-4">
        <div>
          <h4 className="font-display font-medium text-lg text-[#2C3E50]">
            {locale === "en" ? "Proposed Adjustment" : "Draf Penyesuaian Rute"}
          </h4>
          <p className="text-sm text-[#5C6D7E] mt-1">
            {draft.summary}
          </p>
        </div>
      </div>

      <div className="space-y-4 mb-6">
        {draft.changes.length > 0 && (
          <div className="bg-[#FAF8F5] rounded-xl p-4 border border-[#E8E0CE]">
            <h5 className="text-xs font-semibold uppercase tracking-wider text-[#5C6D7E] mb-3">
              {locale === "en" ? "Changes" : "Perubahan Utama"}
            </h5>
            <div className="flex flex-col gap-3">
              {draft.changes.map((change, idx) => (
                <div key={idx} className="flex items-center gap-3 text-sm">
                  <div className="flex-1 bg-white border border-[#E8E0CE] rounded-lg p-2 text-center text-[#5C6D7E] line-through">
                    {change.before}
                  </div>
                  <ArrowRight className="w-4 h-4 text-[#D4AF37] shrink-0" />
                  <div className="flex-1 bg-[#2C3E50] text-white border border-[#2C3E50] rounded-lg p-2 text-center font-medium shadow-sm">
                    {change.after}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {draft.unchangedGuarantees.length > 0 && (
          <div className="bg-emerald-50 rounded-xl p-4 border border-emerald-100/50">
            <h5 className="text-xs font-semibold uppercase tracking-wider text-emerald-800 mb-2">
              {locale === "en" ? "Kept Guarantees" : "Tetap Dipertahankan"}
            </h5>
            <ul className="flex flex-col gap-1.5">
              {draft.unchangedGuarantees.map((guarantee, idx) => (
                <li key={idx} className="text-sm text-emerald-700 flex items-start gap-2">
                  <CheckCircle2 className="w-4 h-4 mt-0.5 shrink-0" />
                  <span>{guarantee}</span>
                </li>
              ))}
            </ul>
          </div>
        )}

        {draft.limitations.length > 0 && (
          <div className="bg-amber-50 rounded-xl p-4 border border-amber-100">
            <h5 className="text-xs font-semibold uppercase tracking-wider text-amber-800 mb-2">
              {locale === "en" ? "Please Verify" : "Perlu Diverifikasi"}
            </h5>
            <ul className="flex flex-col gap-1.5">
              {draft.limitations.map((limit, idx) => (
                <li key={idx} className="text-sm text-amber-700 flex items-start gap-2">
                  <ShieldAlert className="w-4 h-4 mt-0.5 shrink-0" />
                  <span>{limit}</span>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>

      <div className="flex items-center gap-3">
        <button
          onClick={onCancel}
          className="flex-1 py-3 px-4 rounded-xl font-medium text-[#5C6D7E] bg-[#FAF8F5] border border-[#E8E0CE] hover:bg-[#F0EBE1] transition-colors"
        >
          {locale === "en" ? "Keep Original" : "Pertahankan Rute"}
        </button>
        <button
          onClick={onApply}
          className="flex-1 py-3 px-4 rounded-xl font-medium text-white bg-[#D4AF37] hover:bg-[#B3932F] shadow-sm transition-colors"
        >
          {locale === "en" ? "Apply Draft" : "Terapkan Draft Ini"}
        </button>
      </div>
    </div>
  );
}

