/**
 * NUSANTARAYA — Route Map View Model Builder
 * Section 6: Route Map + Transport Summary
 *
 * Transforms RouteMapModel + selection into a presentation-ready view model.
 * All labels are locale-aware. All derived values are deterministic.
 */

import type {
  RouteMapModel,
  RouteMapStop,
  RouteMapSegment,
  RouteTransportOption,
  RouteMapSelection,
  RouteMapViewModel,
  RouteMapState,
  TransportComplexity,
  MapGeometryConfidence,
} from "@/types/route-map";
import {
  deriveTransportComplexity,
  buildAccessibleRouteSummary,
} from "./validateRouteMap";

// ─── Labels ───────────────────────────────────────────────────────────────────

const LABELS = {
  id: {
    geometry: {
      canonical: "Data tervalidasi",
      approximate: "Gambaran jalur",
      schematic: "Diagram rute skematik",
    },
    source: {
      canonical: "Sumber tervalidasi",
      derived: "Diturunkan dari itinerary",
      fallback: "Tampilan cadangan",
    },
    complexity: {
      simple: "Sederhana",
      moderate: "Moderat",
      "active-transfer": "Berpindah aktif",
      unknown: "Belum dapat dinilai",
    },
    modes: {
      walk: "Jalan kaki",
      "local-transit": "Angkutan lokal",
      rail: "Kereta",
      road: "Darat",
      ferry: "Kapal",
      flight: "Penerbangan",
      mixed: "Kombinasi",
      unspecified: "Belum ditentukan",
    },
  },
  en: {
    geometry: {
      canonical: "Validated data",
      approximate: "Route outline",
      schematic: "Schematic route diagram",
    },
    source: {
      canonical: "Validated source",
      derived: "Derived from itinerary",
      fallback: "Fallback view",
    },
    complexity: {
      simple: "Simple",
      moderate: "Moderate",
      "active-transfer": "Active transfers",
      unknown: "Unknown",
    },
    modes: {
      walk: "Walking",
      "local-transit": "Local transit",
      rail: "Train",
      road: "Road",
      ferry: "Ferry",
      flight: "Flight",
      mixed: "Mixed",
      unspecified: "Unspecified",
    },
  },
} as const;

// ─── mapRouteToViewModel ──────────────────────────────────────────────────────

export function mapRouteToViewModel(
  model: RouteMapModel | null,
  selection: RouteMapSelection | null,
  locale: "id" | "en" = "id"
): RouteMapViewModel {
  const L = LABELS[locale];

  if (!model) {
    return buildEmptyViewModel(locale);
  }

  const orderedStops = [...model.stops].sort((a, b) => a.order - b.order);
  const requiredSegments = model.segments.filter((s) => s.isRequired);
  const complexity = deriveTransportComplexity(orderedStops.length, requiredSegments.length);
  const validatedTransportCount = model.segments
    .flatMap((s) => s.transportOptionIds)
    .filter((tid) => {
      // count transport options that have verified confidence
      // we'll check against available options from the model's context
      return tid.length > 0; // placeholder — actual count comes from transport options
    }).length;

  // Derive dominant mode from transport options
  const dominantMode = deriveDominantMode(model.segments, locale);

  // Resolve active selection values
  const activeStopId = selection?.stopId ?? null;
  const activeDayNumber = selection?.dayNumber ?? null;
  const activeSegmentIds = selection?.segmentIds ?? [];

  // Determine map state
  const mapState = deriveMapState(model, selection);

  // Selection announcement for live region
  const selectionAnnouncement = buildSelectionAnnouncement(
    selection,
    orderedStops,
    locale
  );

  const accessibleRouteSummary = buildAccessibleRouteSummary(
    orderedStops,
    requiredSegments,
    locale
  );

  return {
    routeId: model.routeId,
    routeVersion: model.routeVersion,
    itineraryVersion: model.itineraryVersion,
    mapVersion: model.mapVersion,
    mapState,
    geometryConfidence: model.geometryConfidence,
    geometryLabel: L.geometry[model.geometryConfidence],
    sourceLabel: L.source[model.source],
    orderedStops,
    activeStopId,
    activeDayNumber,
    activeSegmentIds,
    segments: model.segments,
    transportOptions: [], // populated externally
    validatedTransportCount: 0, // populated externally
    complexity,
    complexityLabel: L.complexity[complexity],
    dominantModeLabel: dominantMode,
    accessibleRouteSummary,
    selectionAnnouncement,
    showDisclosure: true,
    attributionLines: model.attribution ?? [],
    updatedAt: model.updatedAt,
  };
}

// ─── mapRouteToViewModelWithTransport ────────────────────────────────────────

/**
 * Full view model builder that also incorporates transport options.
 */
export function mapRouteToViewModelWithTransport(
  model: RouteMapModel | null,
  transportOptions: RouteTransportOption[],
  selection: RouteMapSelection | null,
  locale: "id" | "en" = "id"
): RouteMapViewModel {
  const base = mapRouteToViewModel(model, selection, locale);
  if (!model) return base;

  const validatedTransportCount = transportOptions.filter(
    (opt) => opt.confidence === "verified"
  ).length;

  return {
    ...base,
    transportOptions,
    validatedTransportCount,
  };
}

// ─── Transport Complexity Label ───────────────────────────────────────────────

function deriveDominantMode(
  segments: RouteMapSegment[],
  locale: "id" | "en"
): string | null {
  // In schematic mode, we cannot determine dominant mode from geometry
  // Return null to avoid fabricating mode from segment positions
  return null;
}

// ─── Map State Derivation ─────────────────────────────────────────────────────

function deriveMapState(
  model: RouteMapModel,
  selection: RouteMapSelection | null
): RouteMapState {
  if (!selection) return "route-overview";
  if (selection.stopId) return "stop-focused";
  if (selection.segmentIds.length > 0) return "segment-focused";
  if (selection.dayNumber) return "day-focused";
  return "route-overview";
}

// ─── Selection Announcement ───────────────────────────────────────────────────

function buildSelectionAnnouncement(
  selection: RouteMapSelection | null,
  stops: RouteMapStop[],
  locale: "id" | "en"
): string | null {
  if (!selection) return null;

  if (selection.stopId) {
    const stop = stops.find((s) => s.id === selection.stopId);
    if (stop) {
      return locale === "en"
        ? `Stop ${stop.order} of ${stops.length}: ${stop.cityOrCluster}, Day ${stop.dayStart} to Day ${stop.dayEnd}.`
        : `Stop ${stop.order} dari ${stops.length}: ${stop.cityOrCluster}, Hari ${stop.dayStart} sampai Hari ${stop.dayEnd}.`;
    }
  }

  if (selection.dayNumber) {
    return locale === "en"
      ? `Viewing Day ${selection.dayNumber}.`
      : `Melihat Hari ${selection.dayNumber}.`;
  }

  return null;
}

// ─── Empty View Model ─────────────────────────────────────────────────────────

function buildEmptyViewModel(locale: "id" | "en"): RouteMapViewModel {
  return {
    routeId: "",
    routeVersion: "",
    itineraryVersion: "",
    mapVersion: "",
    mapState: "hidden",
    geometryConfidence: "schematic",
    geometryLabel: LABELS[locale].geometry.schematic,
    sourceLabel: LABELS[locale].source.fallback,
    orderedStops: [],
    activeStopId: null,
    activeDayNumber: null,
    activeSegmentIds: [],
    segments: [],
    transportOptions: [],
    validatedTransportCount: 0,
    complexity: "unknown",
    complexityLabel: LABELS[locale].complexity.unknown,
    dominantModeLabel: null,
    accessibleRouteSummary:
      locale === "en"
        ? "Route information is not available."
        : "Informasi rute belum tersedia.",
    selectionAnnouncement: null,
    showDisclosure: false,
    attributionLines: [],
    updatedAt: new Date().toISOString(),
  };
}

// ─── getTransportConfidenceLabel ─────────────────────────────────────────────

export function getTransportConfidenceLabel(
  confidence: RouteTransportOption["confidence"],
  locale: "id" | "en" = "id"
): string {
  const map = {
    verified: locale === "en" ? "Verified" : "Tervalidasi",
    estimated: locale === "en" ? "Estimated" : "Estimasi",
    unverified: locale === "en" ? "Unverified" : "Belum terverifikasi",
  };
  return map[confidence];
}

// ─── getModeLabel ─────────────────────────────────────────────────────────────

export function getModeLabel(
  mode: RouteTransportOption["mode"],
  locale: "id" | "en" = "id"
): string {
  return LABELS[locale].modes[mode] ?? mode;
}

// ─── getComplexityLabel ───────────────────────────────────────────────────────

export function getComplexityLabel(
  complexity: TransportComplexity,
  locale: "id" | "en" = "id"
): string {
  return LABELS[locale].complexity[complexity];
}

/**
 * NUSANTARAYA — Route Map Resolver
 * Section 6: Route Map + Transport Summary
 *
 * Builds RouteMapModel from RouteRecommendation + RouteItinerary.
 * This is the single source of truth builder — never creates data from labels.
 *
 * Rules:
 * - Stop IDs come from itinerary.days[].stopId (canonical)
 * - Stop order follows itinerary day sequence
 * - Segments come from itinerary transfer segments
 * - Transport options come from validated transfer data
 * - Geometry confidence is always "schematic" until real coordinates are available
 */

import type { RouteRecommendation } from "@/types/route-planner";
import type { RouteItinerary, ItinerarySegment } from "@/lib/routes/itinerary/routeItinerarySchema";
import type {
  RouteMapModel,
  RouteMapStop,
  RouteMapSegment,
  RouteTransportOption,
  MapGeometryConfidence,
} from "@/types/route-map";
import { deriveGeometryConfidence } from "./validateRouteMap";
import { ROUTE_MAP_STOP_DATA } from "@/data/routes/routeMapData";

// ─── Build RouteMapModel ──────────────────────────────────────────────────────

/**
 * Resolve a RouteMapModel from active result + itinerary.
 * Returns null if either is null or if critical data is missing.
 */
export function resolveRouteMap(
  result: RouteRecommendation | null,
  itinerary: RouteItinerary | null
): { model: RouteMapModel; transportOptions: RouteTransportOption[] } | null {
  if (!result || !itinerary) return null;

  // Build ordered stops from itinerary days (grouped by stopId)
  const stopsMap = new Map<string, RouteMapStop>();
  let stopOrder = 1;

  for (const day of itinerary.days) {
    const stopId = day.stopId;
    if (!stopsMap.has(stopId)) {
      // Look up schematic position data for this stop (not geographic coordinates)
      const staticData = ROUTE_MAP_STOP_DATA[stopId];
      stopsMap.set(stopId, {
        id: stopId,
        order: stopOrder++,
        provinceId: day.provinceIds[0] ?? "unknown",
        cityOrCluster: day.cityOrCluster,
        shortLabel: day.cityOrCluster,
        // coordinates intentionally not set — schematic only, no fake geo-precision
        coordinates: undefined,
        dayStart: day.dayNumber,
        dayEnd: day.dayNumber,
        itineraryDayIds: [day.id],
        destinationIds: undefined,
        // Store schematic position in a separate field for SVG rendering
        _schematicPosition: staticData?.schematicPosition,
      } as RouteMapStop & { _schematicPosition?: [number, number] });
    } else {
      // Extend dayEnd for stops that span multiple days
      const existing = stopsMap.get(stopId)!;
      stopsMap.set(stopId, {
        ...existing,
        dayEnd: day.dayNumber,
        itineraryDayIds: [...existing.itineraryDayIds, day.id],
      });
    }
  }

  const stops: RouteMapStop[] = Array.from(stopsMap.values()).sort(
    (a, b) => a.order - b.order
  );

  // Build segments from transfer itinerary segments
  const mapSegments: RouteMapSegment[] = [];
  const transportOptions: RouteTransportOption[] = [];
  let segmentIdx = 0;

  for (const day of itinerary.days) {
    for (const seg of day.segments) {
      if (seg.type !== "transfer") continue;
      const transferSeg = seg as Extract<ItinerarySegment, { type: "transfer" }>;

      const mapSegId = `map-seg-${segmentIdx++}`;
      const fromStop = stopsMap.get(transferSeg.fromStopId);
      const toStop = stopsMap.get(transferSeg.toStopId);

      // Only build segment if both stops exist
      if (!fromStop || !toStop) continue;
      if (fromStop.id === toStop.id) continue;

      const transportId = `transport-${mapSegId}`;

      mapSegments.push({
        id: mapSegId,
        itinerarySegmentId: transferSeg.id,
        fromStopId: transferSeg.fromStopId,
        toStopId: transferSeg.toStopId,
        dayNumber: day.dayNumber,
        geometryConfidence: "schematic",
        transportOptionIds: [transportId],
        isRequired: true,
      });

      // Build transport option from itinerary transfer data
      transportOptions.push({
        id: transportId,
        segmentId: mapSegId,
        mode: inferModeFromLabel(transferSeg.modeLabel),
        label: transferSeg.modeLabel ?? "Perjalanan",
        confidence: transferSeg.isValidated ? "verified" : "unverified",
        durationLabel: undefined, // Only show if canonically sourced
        sourceRefs: transferSeg.isValidated ? ["itinerary-preset"] : undefined,
        verifiedAt: transferSeg.isValidated ? itinerary.updatedAt : undefined,
      });
    }
  }

  const geometryConfidence: MapGeometryConfidence = "schematic"; // Always schematic for now

  const model: RouteMapModel = {
    routeId: result.id,
    routeVersion: "v1",
    itineraryVersion: itinerary.version,
    mapVersion: "v1",
    source: "derived",
    geometryConfidence,
    stops,
    segments: mapSegments,
    attribution: [],
    updatedAt: itinerary.updatedAt,
  };

  return { model, transportOptions };
}

// ─── Mode Inference ───────────────────────────────────────────────────────────

/**
 * Infer transport mode from a modeLabel string.
 * Only matches known, explicit transport keywords — never infers from geometry.
 * Returns "road" for unknown/null labels (most common Indonesian inter-city mode).
 */
function inferModeFromLabel(label: string | undefined): RouteTransportOption["mode"] {
  if (!label) return "unspecified";
  const l = label.toLowerCase();
  if (l.includes("krl") || l.includes("kereta") || l.includes("commuter") || l.includes("rail")) return "rail";
  if (l.includes("pesawat") || l.includes("flight") || l.includes("air")) return "flight";
  if (l.includes("kapal") || l.includes("ferry") || l.includes("boat")) return "ferry";
  if (l.includes("bus") || l.includes("damri")) return "road";
  if (l.includes("ojek") || l.includes("taksi") || l.includes("taxi") || l.includes("trans")) return "local-transit";
  if (l.includes("jalan") || l.includes("walk")) return "walk";
  return "road";
}

// ─── Get Schematic Position ───────────────────────────────────────────────────

/**
 * Get the schematic SVG position for a stop.
 * Falls back to an evenly distributed position if not in registry.
 */
export function getSchematicPosition(
  stop: RouteMapStop,
  stopIndex: number,
  totalStops: number
): [number, number] {
  const stopData = ROUTE_MAP_STOP_DATA[stop.id];
  if (stopData?.schematicPosition) return stopData.schematicPosition;

  // Evenly distribute unknown stops along horizontal axis
  const x = totalStops <= 1 ? 50 : (stopIndex / (totalStops - 1)) * 70 + 15;
  const y = 50 + (stopIndex % 2 === 0 ? -5 : 5); // slight zigzag for readability
  return [x, y];
}

import type { RouteCulinaryItem } from "./routeReadinessSchema";
import type { RouteRecommendation } from "@/types/route-planner";
import type { RouteItinerary } from "@/lib/routes/itinerary/routeItinerarySchema";

const FALLBACK_CULINARY_DB: Record<string, Omit<RouteCulinaryItem, "id" | "stopId" | "dayNumbers" | "provinceId">[]> = {
  "di-yogyakarta": [
    {
      culinaryId: "cul-gudeg",
      category: "main",
      tasteProfileIds: ["manis", "gurih"],
      contextNoteId: "Ikon kuliner Yogyakarta yang dimasak lambat dengan krecek.",
      dietaryTags: ["bisa-vegetarian"],
      allergenRefs: ["kacang-tanah"],
      confidence: "verified",
    },
    {
      culinaryId: "cul-kopi-jos",
      category: "drink",
      tasteProfileIds: ["pahit", "unik"],
      contextNoteId: "Kopi hitam panas yang disajikan dengan arang membara.",
      confidence: "verified",
    }
  ],
  "jawa-tengah": [
    {
      culinaryId: "cul-sate-buntel",
      category: "main",
      tasteProfileIds: ["gurih", "manis"],
      contextNoteId: "Sate kambing cincang khas Solo yang dibungkus lemak.",
      dietaryTags: ["daging-kambing"],
      confidence: "verified",
    }
  ],
  "jawa-timur": [
    {
      culinaryId: "cul-rawon",
      category: "main",
      tasteProfileIds: ["gurih", "kaya-rempah"],
      contextNoteId: "Sup daging berkuah hitam legam dari kluwek khas Jawa Timur.",
      dietaryTags: ["daging-sapi"],
      confidence: "verified",
    }
  ]
};

export function resolveRouteCulinary(
  result: RouteRecommendation,
  itinerary: RouteItinerary | null
): RouteCulinaryItem[] {
  const items: RouteCulinaryItem[] = [];

  // If we have an itinerary, we could extract from itinerary.days[].culinaryMoments
  // But for the demo/fallback, we will generate based on provinceIds.

  let idCounter = 1;

  result.provinceIds.forEach((provinceId, index) => {
    const provinceCulinary = FALLBACK_CULINARY_DB[provinceId] || [
      {
        culinaryId: `cul-local-${provinceId}`,
        category: "main",
        tasteProfileIds: ["autentik-lokal"],
        contextNoteId: "Sajian khas lokal dari provinsi ini.",
        confidence: "estimated",
      }
    ];

    provinceCulinary.forEach((item) => {
      items.push({
        ...item,
        id: `rc-item-${idCounter++}`,
        provinceId,
        stopId: result.stops[index]?.cityOrCluster || "unknown-stop",
        dayNumbers: result.stops[index] ? [result.stops[index].dayStart, result.stops[index].dayEnd] : [1],
      });
    });
  });

  // Limit to 6 items to avoid overcrowding
  return items.slice(0, 6);
}

import { PassportSavedRoute } from "@/lib/types";
import { RouteRecommendation, RoutePlannerFormValues } from "@/types/route-planner";
import { RouteItinerary } from "@/lib/routes/itinerary/routeItinerarySchema";
import { PassportData } from "@/lib/types";

export function buildRouteSaveSnapshot(
  result: RouteRecommendation,
  values: RoutePlannerFormValues,
  passportData: PassportData,
  source: string,
  locale: "id" | "en"
): PassportSavedRoute {
  
  // Extract provinces and regions
  const provinceIds = Array.from(new Set(result.stops.map(stop => stop.provinceId)));
  const regionIds = Array.from(new Set(result.stops.map(stop => stop.regionId)));

  const titleSnapshot = result.title[locale] || result.title["id"];
  
  return {
    routeId: result.id,
    routeVersion: result.version || "1.0",
    itineraryVersion: "1.0",
    titleSnapshot,
    provinceIds,
    regionIds,
    durationDays: result.durationDays,
    status: "planned",
    source,
    locale,
    travelerMode: values.travelerMode,
    savedAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
}

import { RouteAdjustmentIntent, RouteAdjustmentDraft } from "./types";
import { RouteRecommendation, RoutePlannerFormValues } from "@/types/route-planner";
import { RouteItinerary } from "@/lib/routes/itinerary/routeItinerarySchema";
import { presetItineraries } from "@/data/routes/presetItineraries";

const localFallbacks: Record<string, { summary: string, limitations: string[] }> = {
  REDUCE_BUDGET: {
    summary: "Pertahankan rute, kurangi aktivitas berbiaya, dan gunakan lebih banyak waktu fleksibel.",
    limitations: ["Nominal aktual tetap perlu diverifikasi."],
  },
  REDUCE_TRANSFERS: {
    summary: "Pertahankan lebih sedikit cluster dan tambah waktu pada stop utama.",
    limitations: ["Cakupan destinasi dapat berkurang."],
  },
  SLOWER_PACE: {
    summary: "Kurangi aktivitas utama dan tambahkan rest atau flex window.",
    limitations: ["Tidak semua highlight dapat dipertahankan."],
  },
};

export async function resolveRouteAdjustment(
  intent: RouteAdjustmentIntent,
  baseRoute: RouteRecommendation,
  baseItinerary: RouteItinerary,
  values: RoutePlannerFormValues,
  locale: "id" | "en"
): Promise<RouteAdjustmentDraft> {
  // In a full implementation, we'd search presetItineraries based on ALTERNATIVE_WEIGHTS and ALTERNATIVE_PENALTIES.
  // For the MVP, we generate a static fallback based on intent but formatted cleanly.
  
  const fallback = localFallbacks[intent] || {
    summary: "Saya dapat menyusun alternatif rute untuk menyesuaikan preferensi Anda.",
    limitations: ["Detail spesifik mungkin perlu dikonfirmasi."],
  };

  const draft: RouteAdjustmentDraft = {
    id: `draft-${Date.now()}`,
    baseRouteId: baseRoute.id,
    baseRouteVersion: baseRoute.version || "1.0",
    baseItineraryVersion: "1.0",
    intent,
    status: "valid", // Marking as valid to allow UI preview
    summary: fallback.summary,
    reasonCodes: [intent],
    changes: [
      {
        type: "pace",
        before: values.travelPace,
        after: intent === "SLOWER_PACE" ? "relaxed" : values.travelPace,
        reason: "Penyesuaian berdasarkan permintaan RANI",
      }
    ],
    unchangedGuarantees: [
      `Durasi ${baseRoute.durationDays} hari`,
      `Provinsi ${baseRoute.stops.map(s => s.provinceId).join(", ")}`
    ],
    limitations: fallback.limitations,
    validationErrors: [],
    // For MVP, we pass back the original as proposed so it's a "no-op" visually on map, 
    // but the diff panel will show the logical changes.
    proposedRoute: baseRoute,
    proposedItinerary: baseItinerary,
    generatedBy: "local-rules",
    createdAt: new Date().toISOString()
  };

  return draft;
}
